// Frozen reference panels, loaded from data/culture/panels.json (generated by
// `npm run data-check -- panels`; do not edit it by hand).
//
// Qloo affinity only compares within one call, so every scoring call sends Qloo's picks, any
// Control picks and one of these panels together (filter.results.entities or filter.results.tags)
// and reports a pick as "beats N of M reference artists". Each panel is 25 real entities or tags
// from the recorded audience lists of all 9 candidates, spread evenly across Qloo popularity, at
// most 3 from any one candidate, never a seed or a Control pick, and never a name the minor or
// ethnicity guardrails flag (panel names appear in receipts). A panel entry can be one of some
// audience's own top picks; that audience's comparison leaves it out, so M can be under 25.
// `request` names the recording each came from. Changing a panel changes every score, so panels
// are frozen once a scoring call has used them.
//
// The panels are Qloo response data, so they live in a data file the public mirror leaves out,
// never in code. The file is read on first use (not at import), so modules that import this one
// still load without it; a call then throws with the command that generates it. Server and scripts only.
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { z } from "zod";

export interface PanelEntry {
  id: string;
  name: string;
  popularity: number;
  request: string;
}

export const ENTITY_PANEL_TYPES = ["artist", "brand", "movie", "tv_show"] as const;
export const TAG_PANEL_KINDS = ["music", "tone"] as const;
export type EntityPanelType = (typeof ENTITY_PANEL_TYPES)[number];
export type TagPanelKind = (typeof TAG_PANEL_KINDS)[number];

export interface ReferencePanels {
  entity: Readonly<Record<EntityPanelType, readonly PanelEntry[]>>;
  tag: Readonly<Record<TagPanelKind, readonly PanelEntry[]>>;
}

export const PANELS_FILE = path.join("data", "culture", "panels.json");

const entrySchema = z.object({ id: z.string().min(1), name: z.string(), popularity: z.number(), request: z.string() }).strict();
const panelSchema = z.array(entrySchema).min(1);
const fileSchema = z.object({
  source: z.string(),
  built: z.string(),
  entity: z.object({ artist: panelSchema, brand: panelSchema, movie: panelSchema, tv_show: panelSchema }).strict(),
  tag: z.object({ music: panelSchema, tone: panelSchema }).strict(),
});

/** Validates the panels file's contents. */
export function parsePanels(json: unknown): ReferencePanels {
  const { entity, tag } = fileSchema.parse(json);
  return { entity, tag };
}

/**
 * Reads and validates data/culture/panels.json under the working directory. Throws with the
 * generating command when it is missing. The path is written out in full so the build's file tracer
 * can follow it (a computed path makes it trace the whole project).
 */
export function loadPanels(): ReferencePanels {
  if (!existsSync(path.join(process.cwd(), "data", "culture", "panels.json"))) {
    throw new Error(
      `The frozen reference panels are missing (${PANELS_FILE}). They are Qloo response data, so the public repository leaves them out. Generate them from your own recordings with \`npm run data-check -- panels\` (README: "Data and the Qloo API").`,
    );
  }
  return parsePanels(JSON.parse(readFileSync(path.join(process.cwd(), "data", "culture", "panels.json"), "utf8")));
}

let cached: ReferencePanels | undefined;

/** The frozen panels, read and checked once per process. */
export function referencePanels(): ReferencePanels {
  cached ??= loadPanels();
  return cached;
}

/** The reference panel for one scored entity type. */
export const entityPanel = (type: EntityPanelType): readonly PanelEntry[] => referencePanels().entity[type];

/** The reference panel for one tag kind (music genres or emotional tones). */
export const tagPanel = (kind: TagPanelKind): readonly PanelEntry[] => referencePanels().tag[kind];

/** Every entity panel entry, all types together. */
export const entityPanelEntries = (): PanelEntry[] => ENTITY_PANEL_TYPES.flatMap((type) => entityPanel(type));
